//#region src/core/builders/sdk/master-layout-crud-xml.d.ts
/** Result of a successful master/layout CRUD operation. */
interface MasterLayoutCrudSuccess {
  ok: true;
  handler: PptxHandler;
  data: PptxData;
}
/** Result of a rejected master/layout CRUD operation. */
interface MasterLayoutCrudFailure {
  ok: false;
  /** `notFound`: the id did not resolve. `inUse`: a slide references the
   * part. `lastMaster`: refusing to delete the presentation's only master. */
  reason: 'notFound' | 'inUse' | 'lastMaster';
}
type MasterLayoutCrudResult = MasterLayoutCrudSuccess | MasterLayoutCrudFailure;
//#endregion
//#region src/core/builders/sdk/master-layout-crud-layout.d.ts
/** {@link duplicateLayout} / {@link insertLayout} success: the new layout's id. */
interface DuplicateLayoutSuccess {
  ok: true;
  handler: PptxHandler;
  data: PptxData;
  layoutId: string;
}
type DuplicateLayoutResult = DuplicateLayoutSuccess | MasterLayoutCrudFailure;
/**
 * Deep-copy a layout (elements, background, placeholders, and any part it
 * references, such as an embedded picture) within its own master, naming it
 * with PowerPoint's "duplicate" convention ({@link uniqueDisplayName}).
 */
