/**
 * Remove a layout. Refuses when a slide still references it (`inUse`) or the
 * id does not resolve (`notFound`); the caller should re-point or delete
 * those slides first.
 */
declare function deleteLayout(handler: PptxHandler, data: PptxData, layoutId: string): Promise<MasterLayoutCrudResult>;
/** Rename a layout (`p:cSld/@name`) via the existing typed-model save path. */
declare function renameLayout(handler: PptxHandler, data: PptxData, layoutId: string, name: string): Promise<MasterLayoutCrudResult>;
/**
 * Add a new layout to a master. Delegates to {@link createLayout}; when no
 * `definition` is supplied a default title-only layout is generated, named
 * with {@link uniqueDisplayName}.
 */
declare function insertLayout(handler: PptxHandler, data: PptxData, masterId: string, definition?: LayoutDefinition): Promise<DuplicateLayoutResult>;
//#endregion
//#region src/core/builders/sdk/master-layout-crud-master.d.ts
/** {@link duplicateSlideMaster} / {@link insertSlideMaster} success: the new master's id. */
interface DuplicateMasterSuccess {
  ok: true;
  handler: PptxHandler;
  data: PptxData;
  masterId: string;
}
type DuplicateMasterResult = DuplicateMasterSuccess | MasterLayoutCrudFailure;
/**
 * Deep-copy a slide master together with every layout it owns, naming it
 * with PowerPoint's "duplicate master" convention ({@link uniquePrefixedName}).
 * The new master shares its source's theme part rather than forking a copy.
 */
declare function duplicateSlideMaster(handler: PptxHandler, data: PptxData, masterId: string): Promise<DuplicateMasterResult>;
/**
 * Remove a slide master and every layout it owns. Refuses when it is the
 * presentation's only master (`lastMaster`) or a slide still uses one of its
 * layouts (`inUse`).
 */
declare function deleteSlideMaster(handler: PptxHandler, data: PptxData, masterId: string): Promise<MasterLayoutCrudResult>;
/** Rename a slide master (`p:cSld/@name`) via the existing typed-model save path. */
declare function renameSlideMaster(handler: PptxHandler, data: PptxData, masterId: string, name: string): Promise<MasterLayoutCrudResult>;
/**
 * Insert a brand-new slide master: PowerPoint's own eleven standard layouts
 * ({@link STANDARD_LAYOUTS}, the same set `PresentationBuilder` seeds a
 * from-scratch deck with), the first master's colour map and text styles
 * byte-copied across, sharing its theme part.
 */
declare function insertSlideMaster(handler: PptxHandler, data: PptxData): Promise<DuplicateMasterResult>;
